using System.IO;
using System.IO.Path;
using Microsoft.Azure;
using Blobstorage = Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Blob;
using Microsoft.Dynamics.Platform.Integration.SharePoint;
using Microsoft.Dynamics.ApplicationPlatform.Services.Instrumentation;
using Microsoft.DynamicsOnline.Infrastructure.Components.SharedServiceUnitStorage;
using Microsoft.Dynamics.AX.Framework.FileManagement;
/// <summary>
/// CB521_ExciseREgister
/// Class used for NAT3040 reporting
/// </summary>
public class METNature3040ReportController extends SrsReportRunController
{
    #define.ExcelExtension('.xlsx')
    METNature3040ReportContract             contract;
    NumberSeq                       numberSeqNat30;
    NumberSeq                       numberSeqNat40;
    METNat30Number                  metNat30Number;
    METNat40Number                  metNat40Number;

    METProcMetrics                  procMetrics;

}

Method.Source:
    /// <summary>
    /// This method is a main method of class
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METNature3040ReportController controller = new METNature3040ReportController();

        if (args.menuItemName() == menuItemActionStr(METNature30Report))
        {
            controller.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
        }
        else if (args.menuItemName() == menuItemActionStr(METNature40Report))
        {
            controller.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
        }

        controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        controller.parmArgs(args);
        controller.startOperation();
    }

    /// <summary>
    /// Create report execution record
    /// </summary>
    /// <param name = "_reportContract">contract</param>
    public void createReportExecution(METNature3040ReportContract   _reportContract)
    {
        METNature3040ReportExecution   reportExecution;

        reportExecution.clear();
        reportExecution.Nat3040ReportNumber = _reportContract.parmNat30Number();
        reportExecution.NAT3040 = _reportContract.parmMETNat3040();
        reportExecution.insert();
    }

    /// <summary>
    /// run method
    /// </summary>
    public void run()
    {
        if (this.isInBatch())
        {
            contract =  this.parmReportContract().parmRdpContract() as METNature3040ReportContract;

            METExciseInformationTable               metExciseInformationTable;
            METInventTable                          metInventTable;
            METTariffItemCodeBase                   metTariffItemCodeBase;
            METNAT3040                              metNat3040;

            METReportRunHistory                     lastSucessfulReportRun;
            TransDateTime                           successfulRunDate;
            // Bug 354805: CB521 Nat 40 report report cannot be reviewed in D365
            boolean                                 isReportDataGenerated;

            if (args.menuItemName() == menuItemActionStr(METNature30Report))
            {
                metNat3040 = METNAT3040::NAT30;
                numberSeqNat30 = NumberSeq::newGetNum(VendParameters::METnumRefNat30NumberSeq());
                metNat30Number = numberSeqNat30.num();
                contract.parmNat30Number(metNat30Number);
                this.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
            }
            else if (args.menuItemName() == menuItemActionStr(METNature40Report))
            {
                metNat3040 = METNAT3040::NAT40;
                numberSeqNat40 = NumberSeq::newGetNum(VendParameters::METnumRefNat40NumberSeq());
                metNat40Number = numberSeqNat40.num();
                contract.parmNat30Number(metNat40Number);
                this.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
            }

            contract.parmMETNat3040(metNat3040);

            this.createReportExecution(contract);

            metExciseInformationTable = null;
            METExciseRegisterOriginTypes        originType;

            procMetrics = METProcMetrics::construct(METBatchLogOperation::NAT3040);
            procMetrics.startTrace(1, contract.parmNat30Number());

            using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
            {
                while select SiteId from metExciseInformationTable
                group by SiteId
                    where metExciseInformationTable.Nat3040ReportNumber == ''
                    exists join metInventTable
                        where metInventTable.ItemId == metExciseInformationTable.ItemId
                            exists join metTariffItemCodeBase
                                where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
                                    && metTariffItemCodeBase.NAT3040 == metNat3040
                            exists join originType
                                where originType.ReferenceId == metExciseInformationTable.InventTransType
                                   && originType.UpdateNAT3040 == NoYes::Yes
                {
                    contract.parmSite(metExciseInformationTable.SiteId); //setting site id for current iteration
                    contract.parmSiteName(InventSite::find(metExciseInformationTable.SiteId).Name);
                    contract.parmBondNumber(InventSite::find(metExciseInformationTable.SiteId).METBondNumber);
            
                    this.setDateParameters(contract);

                    METNature3040ReportDataService reportDataService = new METNature3040ReportDataService();
                    reportDataService.parmContract(contract);
                    // Bug 354805: CB521 Nat 40 report report cannot be reviewed in D365
                    isReportDataGenerated = isReportDataGenerated || reportDataService.generateData();
                }

                // Bug 354805: CB521 Nat 40 report report cannot be reviewed in D365
                // if at least one site has report data generated trigger the report
                if (isReportDataGenerated)
                {
                    if (procMetrics)
                    {
                        procMetrics.startDescriptionTime(4, "@MET:NAT30ReportGen");
                    }

                    METNature3040ReportExecute::execute(this);

                    if (procMetrics)
                    {
                        procMetrics.endDescriptionTime(4);
                    }
                }
                // else don't trigger empty report and update the status from in progress to Success
                else
                {
                    Info('@MET:ReportDataNotGenerated');
                    METNature3040ReportExecution   reportExecution;

                    update_recordset reportExecution
                    setting ReportStatus = METNAT3040ReportStatus::Success
                    where reportExecution.Nat3040ReportNumber == contract.parmNat30Number();
                }
                procMetrics.endTrace(isReportDataGenerated ? METBatchMonitoringStatus::Completed : METBatchMonitoringStatus::Failed);
            }
        }
        else
        {
            return;
        }
    }

    /// <summary>
    /// Setting date parameters
    /// </summary>
    /// <param name = "_contract">Contract</param>
    public void setDateParameters(METNature3040ReportContract _contract)
    {
        METReportRunHistory                     lastSucessfulReportRun, lastSucessfulReportRunForReport;
        METExciseInformationTable               metExciseInformationTable;
        TransDate                               currentDate = DateTimeUtil::date(DateTimeUtil::utcNow());
        TransDateTime                           currentDateTime = DateTimeUtil::utcNow();  
        TransDateTime                           siteSpecificDateTime = DateTimeUtil::removeTimeZoneOffset(DateTimeUtil::newDateTime(currentDate, 22*60*60), InventSite::find(_contract.parmSite()).Timezone); // 10 PM


        if (_contract.parmCPI())
        {
            siteSpecificDateTime = currentDateTime;
        }
        select firstonly forupdate LastSuccessfulRun from lastSucessfulReportRun
                where lastSucessfulReportRun.SRSReportName == this.parmReportName() &&
                        lastSucessfulReportRun.Site == _contract.parmSite();

        if (lastSucessfulReportRun.RecId)
        {
            _contract.parmFromDate(DateTimeUtil::removeTimeZoneOffset(DateTimeUtil::newDateTime(this.getLastRunDate(lastSucessfulReportRun), 0), InventSite::find(_contract.parmSite()).Timezone));
            _contract.parmToDate(siteSpecificDateTime);

            ttsbegin;
            lastSucessfulReportRun.LastSuccessfulRun = siteSpecificDateTime;
            lastSucessfulReportRun.update();
            ttsbegin;
        }
        else
        {
            select firstonly LastSuccessfulRun from lastSucessfulReportRunForReport
                where lastSucessfulReportRunForReport.SRSReportName == this.parmReportName();
            
            select firstonly CreatedDateTime from metExciseInformationTable  order by CreatedDateTime
                where metExciseInformationTable.SiteId == _contract.parmSite() &&
                      metExciseInformationTable.Nat3040ReportNumber == '' ;
            
            lastSucessfulReportRun.SRSReportName = this.parmReportName();
            lastSucessfulReportRun.LastSuccessfulRun = siteSpecificDateTime;
            lastSucessfulReportRun.Site = _contract.parmSite();
            lastSucessfulReportRun.insert();

            _contract.parmFromDate(DateTimeUtil::removeTimeZoneOffset(DateTimeUtil::newDateTime(this.getLastRunDate(lastSucessfulReportRunForReport), 0), InventSite::find(_contract.parmSite()).Timezone));
            _contract.parmToDate(siteSpecificDateTime);
        }

        _contract.parmLastRunDateTime(_contract.parmToDate());
    }

/// <summary>
/// get last run date
/// </summary>
/// <param name = "_reportRun">reportRunHistory</param>
/// <returns>transDate</returns>
public TransDate getLastRunDate(METReportRunHistory _reportRun)
{
    return DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(_reportRun.LastSuccessfulRun, InventSite::find(_reportRun.Site).Timezone)) + 1;
}

/// <summary>
/// Not to load last user interaction values
/// </summary>
/// <param name = "_loadFromSysLastValue">Boolean reference</param>
/// <returns>Boolean</returns>
public boolean parmLoadFromSysLastValue(boolean _loadFromSysLastValue = loadFromSysLastValue)
{
    return false;
}

/// <summary>
/// Method to indicate that report must go in batch
/// </summary>
/// <returns>true</returns>
public boolean mustGoBatch()
{
    return true;
}
